import heapq
import sys

L, R, addL, addR, miny = list(), list(), 0, 0, 0

def push_left(x):
  heapq.heappush(L, -x + addL)

def push_right(x):
  heapq.heappush(R, x - addR)

def top_left():
  return -L[0] + addL

def top_right():
  return R[0] + addR

def pop_left():
  return -heapq.heappop(L) + addL

def pop_right():
  return heapq.heappop(R) + addR

def add_xma(a):
  global miny
  if len(L) != 0:
    miny += max(0, top_left() - a)
  push_left(a)
  push_right(pop_left())

def add_amx(a):
  global miny
  if len(R) != 0:
    miny += max(0, a - top_right())
  push_right(a)
  push_left(pop_right())


it = map(int, sys.stdin.buffer.read().split())
N = next(it)
L.extend([0] * (N + 10))
R.extend([0] * (N + 10))

t = 0
for T, D, X in zip(it, it, it):
  addL -= T - t
  addR += T - t
  if D == 0:
    add_amx(X)
  else:
    add_xma(X)
  t = T

print(miny)
